CREATE TABLE case_map_areas (id VARCHAR(36) PRIMARY KEY, case_id VARCHAR(36) NOT NULL, area_type VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NULL, task_id VARCHAR(36) NULL, clue_id VARCHAR(36) NULL, version INT NOT NULL DEFAULT 1, created_by_user_id VARCHAR(36) NOT NULL, reviewed_by_user_id VARCHAR(36) NULL, reviewed_at VARCHAR(40) NULL, starts_at VARCHAR(40) NULL, ends_at VARCHAR(40) NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, CONSTRAINT fk_case_map_areas_case FOREIGN KEY (case_id) REFERENCES cases(id) ON DELETE CASCADE, CONSTRAINT fk_case_map_areas_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE SET NULL, CONSTRAINT fk_case_map_areas_clue FOREIGN KEY (clue_id) REFERENCES clues(id) ON DELETE SET NULL, CONSTRAINT fk_case_map_areas_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id), CONSTRAINT fk_case_map_areas_reviewer FOREIGN KEY (reviewed_by_user_id) REFERENCES users(id), CONSTRAINT chk_case_map_areas_type CHECK (area_type IN ('search','searched','risk','rally')), CONSTRAINT chk_case_map_areas_status CHECK (status IN ('candidate','pending_review','approved','rejected')), CONSTRAINT chk_case_map_areas_version CHECK (version > 0));
-- statement-break
CREATE INDEX idx_case_map_areas_case_status ON case_map_areas(case_id, status, updated_at);
-- statement-break
CREATE TABLE case_map_area_vertices (area_id VARCHAR(36) NOT NULL, vertex_order INT NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, PRIMARY KEY(area_id, vertex_order), CONSTRAINT fk_case_map_area_vertices_area FOREIGN KEY (area_id) REFERENCES case_map_areas(id) ON DELETE CASCADE, CONSTRAINT chk_case_map_area_vertices_lat CHECK (latitude BETWEEN -90 AND 90), CONSTRAINT chk_case_map_area_vertices_lng CHECK (longitude BETWEEN -180 AND 180));
